public=[]
for r in rows:
 m=measure[r['id']];kind=next(iter(m.get('scene',[])),None)
 if not r['plan']['items']:effect='保持原样，不强行安排动作';scope='尊重边界'
 elif r['id']=='C04':effect='只有小狐狸走近街坊并抬爪、摇尾；其他人照常';scope='局部狐狸'
 elif r['id']=='C05':effect='诚实说明做不到建造铁塔，再做简短招呼，不强开庆典';scope='有限回应'
 elif r['id']=='C07':effect='街坊做一个简短招呼，不虚构具体事件';scope='有限回应'
 else:effect,scope=scenes.get(kind,('相关人物做出已有动作',kind or '局部'))
 public.append({'id':r['id'],'split':r['split'],'text':r['text'],'mood':tags.get(r.get('rawAtmosphere',{}).get('choice'),r.get('rawAtmosphere',{}).get('choice')),'plan':r['plan']['summary'],'items':[[i['target'],i['action']] for i in r['plan']['items']],'effect':effect,'scope':scope,'participants':m.get('participants',0),'first_sim_seconds':m.get('firstPhysicalDifference'),'outcome':m.get('outcome'),'api_ms':r.get('ms'),'interpretation_source':(r['plan'].get('resolution') or {}).get('source','literal-selection')})
(dest/'cases.json').write_text(json.dumps(public,ensure_ascii=False,indent=2)+'\n')
ms=sorted(r['ms'] for r in rows);p95=ms[int((len(ms)-1)*.95)];first=[m['firstPhysicalDifference'] for r in rows if r['split']!='control' and (m:=measure[r['id']]).get('firstPhysicalDifference') is not None]
summary={'distinct_cases':49,'meaningful_vibes':42,'controls':7,'meaningful_nonempty':sum(bool(r['plan']['items']) for r in rows if r['split']!='control'),'model':'typesafe/jev-1.14','questions':127,'final_request_median_ms':statistics.median(ms),'final_request_p95_ms':p95,'first_position_or_prop_difference_sim_seconds':{'min':min(first),'median':statistics.median(first),'max':max(first)},'raw_post_count':sum(len(json.loads((out/(name+'.json')).read_text())) for name in ['baseline','revised','final','scope']),'provider_reported_cost_usd':sum(sum(x.get('cost') or 0 for x in json.loads((out/(name+'.json')).read_text())) for name in ['baseline','revised','final','scope']),'frontend_tests':282,'focus_and_scope_included':True,'api_tests':42,'limits':'Authored probes, frozen expectations, finite existing actions. Simulation measurements are not perceptual scores, universal model accuracy, end-to-end browser latency or all-device FPS.'};(out/'summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n')
esc=html.escape
body=''.join(f'<tr data-split="{r["split"]}"><td>{r["id"]}</td><td><button class="copy" data-text="{esc(r["text"],quote=True)}">复制</button>{esc(r["text"])}</td><td>{esc(r["mood"] or "—")}</td><td>{esc(r["effect"])}</td><td>{esc(r["scope"])}'+(f' · {r["participants"]} 人' if r['participants'] else '')+f'</td><td>{r["api_ms"]} ms</td></tr>' for r in public)
page='''<!doctype html><html lang="zh"><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Koyoi · 氛围语言实测</title><style>
:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#23222d;color:#eee2cc;font:16px/1.65 system-ui,sans-serif}main{max-width:1180px;margin:auto;padding:44px 24px 72px}a{color:#edc28a}h1{font:42px Georgia,serif;line-height:1.2;margin:8px 0 22px}h2{font:26px Georgia,serif;margin-top:44px}p{max-width:900px}.eyebrow{color:#c3a47d;font-size:12px;letter-spacing:2px}.muted{color:#b9b2af}.facts{display:flex;flex-wrap:wrap;gap:12px}.fact{border:1px solid #5b4c49;border-radius:12px;padding:14px 20px}.fact b{font-size:25px;display:block}.gallery{display:grid;grid-template-columns:1fr 1fr;gap:18px}figure{margin:0;background:#2c2933;border-radius:14px;overflow:hidden}img{display:block;width:100%}figcaption{padding:12px 16px;font-size:14px}button,input{font:inherit;color:inherit;background:#38323b;border:1px solid #685647;border-radius:8px;padding:8px 12px}button{cursor:pointer}.tools{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}.tools input{flex:1;min-width:200px}.table{overflow:auto}table{width:100%;border-collapse:collapse;font-size:14px}th,td{text-align:left;vertical-align:top;border-bottom:1px solid #4f4246;padding:14px 10px}td:nth-child(2){min-width:280px;max-width:420px}td:nth-child(4){min-width:220px}.copy{font-size:12px;float:right;margin:0 0 6px 8px;padding:3px 8px}details{padding:16px 0;border-top:1px solid #514348}small{font-size:13px}@media(max-width:720px){main{padding:28px 16px}h1{font-size:34px}.gallery{grid-template-columns:1fr}}
</style><main><a href="../../">← 返回今宵小镇</a><p class="eyebrow">KOYOI · FREE-TEXT VERIFICATION · 2026-11-08</p><h1>不是选菜单，<br>也能让小镇听见。</h1><p>这轮输入全部避开已有灰字与快捷按钮原句：36 条新氛围表达，另加 6 条额外表达与 7 条边界测试。逐句真实调用 Jev，再把实际返回的计划放进小镇模拟；7 条代表输入用真实网页渲染查看。</p><div class="facts"><div class="fact"><b>42 / 42</b>氛围表达有可执行回应</div><div class="fact"><b>7 条</b>否定、局部、无法实现等边界</div><div class="fact"><b>282</b>行为回归与聚焦专项</div><div class="fact"><b>42</b>云端接口检查</div></div><p class="muted">这些是本轮人工编写的探针，不是随机抽取的真实用户样本。“有回应”不等于每种变化都同样醒目，也不代表任意输入都能做到。</p><h2>画面里的回应</h2><div class="gallery"><figure><a href="D02-clean.png"><img src="D02-clean.png" alt="孤单表达触发街坊相聚"></a><figcaption>“热闹从我身边经过，可我还是像个落单的人。”<br>街坊从不同区域走近、停下交谈。图为约 10 秒的实际回放。</figcaption></figure><figure><a href="D13-clean.png"><img src="D13-clean.png" alt="饭香表达触发餐厅聚拢"></a><figcaption>“胃里空空的，想念有人做饭时那股烟火气。”<br>餐厅前开始排队等热食，来自桥边、露台的居民也有位置变化。</figcaption></figure><figure><a href="kindness-handoff.png"><img src="kindness-handoff.png" alt="两位街坊当面递出纸笺"></a><figcaption>“A tiny kindness deserves somewhere to land. Pass it gently from hand to hand.”<br>两位街坊写折纸笺、靠近，再递向对方。图为递出步骤；完整配方另有执行记录。</figcaption></figure><figure><a href="D05-clean.png"><img src="D05-clean.png" alt="疲惫表达触发分散休息"></a><figcaption>“脑子像打了结，想在这里慢慢松开。”<br>约 10 位可移动居民散向歇息位置。这种变化比用餐聚拢更柔和。</figcaption></figure></div><h2>发现的问题与修正</h2><p>首轮“把好意传下去”曾落成泛泛相聚；“把一句谢谢递到某人手里”曾变成挂在树边。现在区分<strong>被温柔接住、把谢意递给别人、把思念留给远方</strong>，分别复用相聚、递笺、挂笺。一个无法实现的建造请求曾误触庆祝，现改为诚实说明和简短回应。</p><p>局部活动依然只有相关人物参与。纸笺与街坊协作的“看近一点”改为对准正在做事的人，镜头由用户主动选择，不自动抢走全景。</p><details><summary>怎样理解这次测试</summary><p>原始自然语言只经过一次 OpenRouter Decisions 调用，模型为 typesafe/jev-1.14，共 127 个有限选择问题。Jev 选择意图；小镇的现有规则把选择变成走路、聚散、取物、写折和交接。没有另加前置生成模型，也没有为每句测试文字写专用触发器。</p><p>第一批 24 条开发表达中有 1 条语义过于笼统；7 条边界中有 1 条错误替换。第一轮另留的 12 条里又发现 1 条递谢意与挂树混淆，随后修正；因此它们不再算完全未参与调整的保留集。最后 6 条额外表达只在最终版本调用。最终表共 49 条不同输入，均保留真实请求和响应。</p><p>每次语言结果还与同起点、同随机种子、不输入愿望的小镇对照。参与者位置或道具首次出现差异为 0.5–2.35 模拟秒；这是决策落地后的模拟测量，不是用户看到变化的真实端到端延迟。少人数活动需要近景，不能把普通居民日常散步冒充本次输入的响应。</p><p>282 项完整前端检查（含局部聚焦和范围保护）、语法与构建通过。42 项 API 检查通过。没有把整张表冒称逐帧完整看完，也没有新的全设备性能或音效听测结论。</p></details><h2>全部 49 条测试句</h2><p class="muted">复制后回到小镇输入。解释可以有多个合理答案；本表记录这次实际得到的一个答案。少数边界句有意要求不改变，或只能得到诚实的有限回应。</p><div class="tools"><input id="search" type="search" placeholder="搜索句子、氛围或变化"><button data-filter="all">全部</button><button data-filter="vibe">氛围表达</button><button data-filter="control">边界测试</button></div><p id="count"></p><div class="table"><table><thead><tr><th>编号</th><th>用户自己的话</th><th>Jev 氛围选择</th><th>实际行为</th><th>参与范围</th><th>请求耗时</th></tr></thead><tbody>ROWS</tbody></table></div><p><a href="cases.json">查看本轮逐句结果数据</a> · <a href="../../">回到小镇试一句</a></p><small class="muted">图片为真实本地网页，对真实 Jev 结果做控制回放；部分截图采用近景以展示局部动作。线上完整链路另用自由输入验收。历史检查记录继续保留。</small></main><script>
let group='all';const trs=[...document.querySelectorAll('tbody tr')];function filter(){const q=document.querySelector('#search').value.toLowerCase();let n=0;for(const tr of trs){tr.hidden=!(group==='all'||(group==='control'?tr.dataset.split==='control':tr.dataset.split!=='control'))||!tr.textContent.toLowerCase().includes(q);if(!tr.hidden)n++;}document.querySelector('#count').textContent='显示 '+n+' / '+trs.length+' 条';}document.querySelector('#search').oninput=filter;for(const b of document.querySelectorAll('[data-filter]'))b.onclick=()=>{group=b.dataset.filter;filter();};for(const b of document.querySelectorAll('.copy'))b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.text);b.textContent='已复制';setTimeout(()=>b.textContent='复制',1400);}catch{b.textContent='请选中文字复制';}};filter();
</script></html>'''.replace('ROWS',body)
